static bool enabled(){const char*p=std::getenv("GGML_GOOSE_CONTEXT_CORE");return !(p&&std::strcmp(p,"0")==0);}
static void same(const char*a,const char*b,const char*m){req((a==nullptr)==(b==nullptr),m);if(a)req(std::strcmp(a,b)==0,m);}
static bool same_double(double a,double b){return (std::isnan(a)&&std::isnan(b))||std::memcmp(&a,&b,sizeof a)==0;}
static int map_value(API &a,int value){int fds[2];req(pipe(fds)==0,"mapping pipe");auto child=fork();req(child>=0,"mapping fork");if(child==0){close(fds[0]);a.ggml_set_abort_callback([](const char*){_exit(91);});auto t=a.ggml_ftype_to_ggml_type((ggml_ftype)value);int x=(int)t;(void)write(fds[1],&x,sizeof x);_exit(0);}close(fds[1]);int x=-999,status=0;auto bytes=read(fds[0],&x,sizeof x);close(fds[0]);req(waitpid(child,&status,0)==child,"mapping wait");req(WIFEXITED(status),"mapping controlled error");if(WEXITSTATUS(status)==91)return -999;req(WEXITSTATUS(status)==0&&bytes==sizeof x,"mapping return");return x;}
